(function() {
    'use strict';

    class TribPNAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Tributación de Personas Naturales';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    amountLabelKey: 'r1_amount_label',
                    amountHintKey: 'r1_amount_hint',
                    amountMin: 100,
                    amountMax: 200,
                    amountStep: 0.5,
                    amountDefault: 150,
                    strategyLabelKey: 'r1_strategy_label',
                    strategyHintKey: 'r1_strategy_hint',
                    strategyOptions: [
                        { value: '5yr', i18nKey: 'r1_strat_5yr' },
                        { value: '3yr', i18nKey: 'r1_strat_3yr' }
                    ],
                    complianceLabelKey: 'r1_compliance_label',
                    complianceHintKey: 'r1_compliance_hint',
                    complianceOptions: [
                        { value: 'no', i18nKey: 'r1_comp_no' },
                        { value: 'yes', i18nKey: 'r1_comp_yes' }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    amountLabelKey: 'r2_amount_label',
                    amountHintKey: 'r2_amount_hint',
                    amountMin: 10,
                    amountMax: 30,
                    amountStep: 0.1,
                    amountDefault: 26.9,
                    strategyLabelKey: 'r2_strategy_label',
                    strategyHintKey: 'r2_strategy_hint',
                    strategyOptions: [
                        { value: '100pct', i18nKey: 'r2_strat_100' },
                        { value: '50pct', i18nKey: 'r2_strat_50' },
                        { value: '0pct', i18nKey: 'r2_strat_0' }
                    ],
                    complianceLabelKey: 'r2_compliance_label',
                    complianceHintKey: 'r2_compliance_hint',
                    complianceOptions: [
                        { value: 'no', i18nKey: 'r2_comp_no' },
                        { value: 'yes', i18nKey: 'r2_comp_yes' }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    amountLabelKey: 'r3_amount_label',
                    amountHintKey: 'r3_amount_hint',
                    amountMin: 0,
                    amountMax: 10,
                    amountStep: 0.5,
                    amountDefault: 2,
                    strategyLabelKey: 'r3_strategy_label',
                    strategyHintKey: 'r3_strategy_hint',
                    strategyOptions: [
                        { value: 'voluntary', i18nKey: 'r3_strat_voluntary' },
                        { value: 'wait', i18nKey: 'r3_strat_wait' },
                        { value: 'negotiate', i18nKey: 'r3_strat_negotiate' }
                    ],
                    complianceLabelKey: 'r3_compliance_label',
                    complianceHintKey: 'r3_compliance_hint',
                    complianceOptions: [
                        { value: 'no', i18nKey: 'r3_comp_no' },
                        { value: 'yes', i18nKey: 'r3_comp_yes' }
                    ]
                },
                {
                    titleKey: 'round4_title',
                    briefingKey: 'round4_briefing',
                    amountLabelKey: 'r4_amount_label',
                    amountHintKey: 'r4_amount_hint',
                    amountMin: 0,
                    amountMax: 10,
                    amountStep: 0.5,
                    amountDefault: 3,
                    strategyLabelKey: 'r4_strategy_label',
                    strategyHintKey: 'r4_strategy_hint',
                    strategyOptions: [
                        { value: 'natural', i18nKey: 'r4_strat_natural' },
                        { value: 'sas', i18nKey: 'r4_strat_sas' }
                    ],
                    complianceLabelKey: 'r4_compliance_label',
                    complianceHintKey: 'r4_compliance_hint',
                    complianceOptions: [
                        { value: 'no', i18nKey: 'r4_comp_no' },
                        { value: 'yes', i18nKey: 'r4_comp_yes' }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    complianceScore: 50,
                    taxLiability: 43.1,
                    penaltyRisk: 0,
                    auditRisk: 75,
                    totalPenalties: 0,
                    reportedIncome: 150,
                    correctIncome: 162,
                    reportedDeductions: 26.9,
                    correctDeductions: 19.9,
                    complianceHistory: [],
                    penaltyHistory: [],
                    auditRiskHistory: [],
                    taxHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    amount: 150,
                    strategy: '5yr',
                    complianceOpt: 'no'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var amountInput = document.getElementById('amountInput');
            if (amountInput) decisions.amount = parseFloat(amountInput.value);

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect) decisions.strategy = strategySelect.value;

            var complianceOptSelect = document.getElementById('complianceOptSelect');
            if (complianceOptSelect) decisions.complianceOpt = complianceOptSelect.value;

            var currentState = window.mySimulation.state;
            var roundIdx = Math.min((currentState.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            if (isNaN(decisions.amount) || decisions.amount < round.amountMin || decisions.amount > round.amountMax) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('amount_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var complianceDelta = 0;
            var penaltyDelta = 0;
            var auditDelta = 0;
            var taxDelta = 0;
            var feedback = '';

            if (roundIdx === 0) {
                var incomeGap = Math.abs(d.amount - 162);
                if (incomeGap <= 1) {
                    complianceDelta += 20;
                    auditDelta -= 20;
                    feedback = window.mySimulation.t('r1_feedback_correct');
                } else if (d.amount >= 155 && d.amount <= 168) {
                    complianceDelta += 10;
                    auditDelta -= 10;
                    penaltyDelta += 0.5;
                    feedback = window.mySimulation.t('r1_feedback_close');
                } else if (d.amount <= 150) {
                    complianceDelta -= 10;
                    penaltyDelta += 2.1;
                    auditDelta += 5;
                    feedback = window.mySimulation.t('r1_feedback_under');
                } else {
                    complianceDelta -= 5;
                    feedback = window.mySimulation.t('r1_feedback_over');
                }

                if (d.strategy === '3yr') {
                    complianceDelta += 5;
                    taxDelta += 0.1;
                    feedback += '<br>' + window.mySimulation.t('r1_dep_correct');
                } else {
                    complianceDelta -= 5;
                    taxDelta -= 0.1;
                    feedback += '<br>' + window.mySimulation.t('r1_dep_wrong');
                }

                if (d.complianceOpt === 'yes') {
                    complianceDelta += 10;
                    penaltyDelta -= 1.0;
                    auditDelta -= 10;
                    feedback += '<br>' + window.mySimulation.t('r1_sporadic_correct');
                } else {
                    complianceDelta -= 10;
                    penaltyDelta += 1.4;
                    auditDelta += 10;
                    feedback += '<br>' + window.mySimulation.t('r1_sporadic_wrong');
                }

                ds.reportedIncome = d.amount;
                taxDelta += (d.amount - 150) * 0.35;

            } else if (roundIdx === 1) {
                var dedGap = Math.abs(d.amount - 19.9);
                if (dedGap <= 1) {
                    complianceDelta += 15;
                    auditDelta -= 10;
                    feedback = window.mySimulation.t('r2_feedback_correct');
                } else if (d.amount > 24) {
                    complianceDelta -= 10;
                    penaltyDelta += 1.5;
                    auditDelta += 10;
                    feedback = window.mySimulation.t('r2_feedback_over');
                } else {
                    complianceDelta += 5;
                    feedback = window.mySimulation.t('r2_feedback_conservative');
                }

                if (d.strategy === '50pct') {
                    complianceDelta += 10;
                    feedback += '<br>' + window.mySimulation.t('r2_miami_correct');
                } else if (d.strategy === '100pct') {
                    complianceDelta -= 10;
                    penaltyDelta += 1.2;
                    auditDelta += 8;
                    feedback += '<br>' + window.mySimulation.t('r2_miami_wrong');
                } else {
                    complianceDelta += 5;
                    taxDelta += 0.5;
                    feedback += '<br>' + window.mySimulation.t('r2_miami_zero');
                }

                if (d.complianceOpt === 'yes') {
                    complianceDelta += 10;
                    penaltyDelta -= 0.7;
                    auditDelta -= 8;
                    feedback += '<br>' + window.mySimulation.t('r2_related_correct');
                } else {
                    complianceDelta -= 5;
                    penaltyDelta += 0.7;
                    auditDelta += 5;
                    feedback += '<br>' + window.mySimulation.t('r2_related_wrong');
                }

                ds.reportedDeductions = d.amount;
                var baseChange = (ds.reportedDeductions - 26.9) * 0.35;
                taxDelta -= baseChange;

            } else if (roundIdx === 2) {
                var budgetFactor = Math.min(d.amount / 5, 1);

                if (d.strategy === 'voluntary') {
                    complianceDelta += 20;
                    penaltyDelta = -(ds.penaltyRisk * 0.6);
                    auditDelta -= 25;
                    taxDelta += ds.penaltyRisk * 0.35;
                    feedback = window.mySimulation.t('r3_voluntary_feedback');
                } else if (d.strategy === 'wait') {
                    complianceDelta -= 10;
                    penaltyDelta += ds.penaltyRisk * 0.5;
                    auditDelta += 10;
                    taxDelta += ds.penaltyRisk * 0.5;
                    feedback = window.mySimulation.t('r3_wait_feedback');
                } else {
                    complianceDelta += 5;
                    penaltyDelta -= (ds.penaltyRisk * 0.3 * budgetFactor);
                    auditDelta -= 10;
                    taxDelta += ds.penaltyRisk * 0.4;
                    feedback = window.mySimulation.t('r3_negotiate_feedback');
                }

                complianceDelta += Math.round(budgetFactor * 5);

                if (d.complianceOpt === 'yes') {
                    complianceDelta += 10;
                    penaltyDelta -= 0.36;
                    auditDelta -= 5;
                    feedback += '<br>' + window.mySimulation.t('r3_separate_correct');
                } else {
                    complianceDelta -= 10;
                    penaltyDelta += 0.36;
                    feedback += '<br>' + window.mySimulation.t('r3_separate_wrong');
                }

            } else if (roundIdx === 3) {
                var compBudgetFactor = Math.min(d.amount / 5, 1);
                complianceDelta += Math.round(compBudgetFactor * 10);
                auditDelta -= Math.round(compBudgetFactor * 15);

                if (d.strategy === 'sas') {
                    complianceDelta += 15;
                    auditDelta -= 10;
                    taxDelta -= 2;
                    feedback = window.mySimulation.t('r4_sas_feedback');
                } else {
                    complianceDelta += 0;
                    feedback = window.mySimulation.t('r4_natural_feedback');
                }

                if (d.complianceOpt === 'yes') {
                    complianceDelta += 10;
                    auditDelta -= 10;
                    feedback += '<br>' + window.mySimulation.t('r4_retention_correct');
                } else {
                    complianceDelta -= 5;
                    feedback += '<br>' + window.mySimulation.t('r4_retention_wrong');
                }
            }

            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + complianceDelta));
            ds.penaltyRisk = Math.max(0, parseFloat((ds.penaltyRisk + penaltyDelta).toFixed(1)));
            ds.auditRisk = Math.max(0, Math.min(100, ds.auditRisk + auditDelta));
            ds.taxLiability = parseFloat((ds.taxLiability + taxDelta).toFixed(1));
            ds.totalPenalties = parseFloat((ds.totalPenalties + Math.max(0, penaltyDelta)).toFixed(1));

            ds.complianceHistory.push(ds.complianceScore);
            ds.penaltyHistory.push(ds.penaltyRisk);
            ds.auditRiskHistory.push(ds.auditRisk);
            ds.taxHistory.push(ds.taxLiability);

            // v1.1.0 P0 FIX: render the next round's briefing/controls synchronously.
            // Old code used setTimeout(...,500); by the time it fired the framework had
            // already incremented state.currentPeriod, so (currentPeriod + 1) overshot by
            // one and rendered round N+2 instead of N+1 — desyncing controls/options/amount
            // range from the round counter for rounds 2-4. Called here (pre-increment)
            // currentPeriod is still N, so (N + 1) correctly targets the next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });

            return {
                period: state.currentPeriod,
                roundName: window.mySimulation.t(this.ROUNDS[roundIdx].titleKey),
                amount: d.amount,
                strategy: d.strategy,
                complianceOpt: d.complianceOpt,
                complianceDelta: complianceDelta,
                complianceScore: ds.complianceScore,
                penaltyRisk: ds.penaltyRisk,
                auditRisk: ds.auditRisk,
                taxLiability: ds.taxLiability,
                feedback: feedback
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('complianceDisplay', 'domainState.complianceScore',
                function(v) { return Math.round(v) + ' / 100'; });
            uiManager.bind('taxDisplay', 'domainState.taxLiability',
                function(v) { return '$' + v.toFixed(1) + 'M'; });
            uiManager.bind('penaltyDisplay', 'domainState.penaltyRisk',
                function(v) { return '$' + v.toFixed(1) + 'M'; });
            uiManager.bind('auditRiskDisplay', 'domainState.auditRisk',
                function(v) { return Math.round(v) + '%'; });

            // v1.1.0 FIX: the framework's Undo restores state + KPIs but does not re-render
            // this sim's custom briefing/controls. Re-render them for the restored round.
            // Deferred so it runs after the framework's own undo handler completes.
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation && window.mySimulation.state) {
                            self._updateBriefing(window.mySimulation.state);
                        }
                    }, 0);
                });
            }
        }

        getChartConfig() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                complianceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_compliance_series'),
                            data: [],
                            borderColor: '#2e7d32',
                            backgroundColor: 'rgba(46,125,50,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: t('chart_audit_series'),
                            data: [],
                            borderColor: '#6a1b9a',
                            backgroundColor: 'rgba(106,27,154,0.08)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.3,
                            borderDash: [6, 3]
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_compliance_title'), color: '#1a2744', font: { size: 13, weight: 'bold' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#5a6a80' }, grid: { color: '#edf0f3' } },
                            x: { ticks: { color: '#5a6a80' }, grid: { display: false } }
                        }
                    }
                },
                riskChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_penalty_series'),
                            data: [],
                            backgroundColor: 'rgba(230,81,0,0.7)',
                            borderColor: '#e65100',
                            borderWidth: 1,
                            borderRadius: 3
                        }, {
                            label: t('chart_tax_series'),
                            data: [],
                            backgroundColor: 'rgba(21,101,192,0.6)',
                            borderColor: '#1565c0',
                            borderWidth: 1,
                            borderRadius: 3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: t('chart_risk_title'), color: '#1a2744', font: { size: 13, weight: 'bold' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#5a6a80' }, grid: { color: '#edf0f3' } },
                            x: { ticks: { color: '#5a6a80' }, grid: { display: false } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.complianceHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                complianceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.complianceHistory },
                        { data: state.domainState.auditRiskHistory }
                    ]
                },
                riskChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.penaltyHistory },
                        { data: state.domainState.taxHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var finalCompliance = lastRecord.results ? lastRecord.results.complianceScore : 50;
            var finalPenalty = lastRecord.results ? lastRecord.results.penaltyRisk : 0;
            var finalAudit = lastRecord.results ? lastRecord.results.auditRisk : 75;
            var finalTax = lastRecord.results ? lastRecord.results.taxLiability : 43.1;

            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var performance = t('perf_beginner');
            if (finalCompliance >= 70 && finalPenalty < 3) performance = t('perf_competent');
            if (finalCompliance >= 85 && finalPenalty < 1) performance = t('perf_expert');

            var insights = [];
            if (finalCompliance >= 85) {
                insights.push(t('insight_excellent'));
            } else if (finalCompliance >= 60) {
                insights.push(t('insight_acceptable'));
            } else {
                insights.push(t('insight_poor'));
            }

            if (finalPenalty > 3) {
                insights.push(t('insight_penalty'));
            }
            if (finalAudit > 50) {
                insights.push(t('insight_audit'));
            }

            return {
                finalCompliance: finalCompliance,
                finalPenalty: finalPenalty,
                finalAuditRisk: finalAudit,
                finalTax: finalTax,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results && results.feedback) {
                return results.feedback;
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Ronda', i18nKey: 'col_round' },
                { key: 'results.amount', label: 'Monto', i18nKey: 'col_amount', formatter: function(v) { return v.toFixed(1) + 'M'; } },
                { key: 'results.complianceDelta', label: 'Cambio Cumpl.', i18nKey: 'col_compliance_delta', formatter: function(v) { return (v >= 0 ? '+' : '') + v; } },
                { key: 'results.complianceScore', label: 'Cumplimiento', i18nKey: 'col_compliance', formatter: function(v) { return v + '/100'; } },
                { key: 'results.penaltyRisk', label: 'Multas', i18nKey: 'col_penalty', formatter: function(v) { return '$' + v.toFixed(1) + 'M'; } },
                { key: 'results.auditRisk', label: 'Riesgo Aud.', i18nKey: 'col_audit', formatter: function(v) { return Math.round(v) + '%'; } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    completion_title:     `Simulation Complete`,
                    chart_compliance_title: `Compliance & Risk`,
                    chart_compliance_series: `Tax Compliance`,
                    chart_audit_series:   `Audit Risk (%)`,
                    chart_risk_title:     `Penalties & Tax`,
                    chart_penalty_series: `Penalty Risk (COP M)`,
                    chart_tax_series:     `Tax (COP M)`,
                    perf_beginner:        `Beginner`,
                    perf_competent:       `Competent`,
                    perf_expert:          `Tax Expert`,
                    insight_excellent:    `Excellent tax management. The return was accurate and the defense strategy was effective.`,
                    insight_acceptable:   `Acceptable management, but with areas to improve. Review expense documentation and income separation.`,
                    insight_poor:         `Tax management had significant errors. A full review of tax obligations is recommended.`,
                    insight_penalty:      `Penalty risk was high. A voluntary amendment significantly reduces sanctions.`,
                    insight_audit:        `Audit risk remains high. Documenting all expenses and separating capital income reduces exposure.`,
                    title:                `Personal Income Taxation`,
                    subtitle:             `Dr. Carlos Alberto Mendoza, CPA — Independent Consultant — Bogota, Colombia`,
                    header_badge:         `DIAN — Income Tax Return`,
                    round_label:          `Round`,
                    period_of:            `of`,
                    compliance_label:     `Tax Compliance`,
                    tax_liability_label:  `Calculated Tax`,
                    penalty_risk_label:   `Penalty Risk`,
                    audit_risk_label:     `Audit Risk`,
                    briefing_heading:     `Situation`,
                    decisions_heading:    `Your Decisions`,
                    history_heading:      `Decision History`,
                    submit_btn:           `Submit Decision`,
                    undo_btn:             `Undo Last Round`,
                    amount_warning:       `The amount is outside the allowed range for this round`,
                    round1_title:         `Tax Return 2024: Correct Tax Bases`,
                    round1_briefing:      `Dr. Mendoza must file his 2024 income tax return. His original records show COP 150M in gross income and COP 26.9M in deductions. However, there are discrepancies: unreported sporadic income (conferences, articles) and questions about the depreciation method for computer equipment.<br><br><strong>Red Flags:</strong> COP 4M unreported sporadic income, 5-year vs 3-year depreciation on laptop (COP 2.4M), sublease income not separated.<br><br>Decide: What total income to report, which depreciation method to use, and whether to include sporadic income.`,
                    round2_title:         `Deduction Review: Travel and Related Parties`,
                    round2_briefing:      `The tax return deductions need review. Dr. Mendoza claimed COP 8.5M in travel expenses, but COP 2.5M was a personal family trip to Cartagena and COP 2.8M was a mixed business/leisure trip to Miami. Additionally, COP 4.2M in consulting fees were paid to his brother — a related party transaction.<br><br><strong>Red Flags:</strong> Non-deductible personal travel, mixed-purpose Miami trip (50% deductible), related-party consulting without market documentation.<br><br>Decide: Total deductions to claim, treatment of the Miami trip, and whether to document the related-party transaction.`,
                    round3_title:         `DIAN Audit Response`,
                    round3_briefing:      `The DIAN has selected Dr. Mendoza for a 2024 income tax audit. The auditor will review bank statements, travel receipts, and third-party expense documentation. The team must decide on a defense strategy.<br><br><strong>Key decision:</strong> File a voluntary amendment (5% penalty) vs. wait for the audit outcome (50% penalty if caught) vs. negotiate a settlement.<br><br>Decide: Defense budget, response strategy, and whether to separate rental income from professional income.`,
                    round4_title:         `Tax Planning for 2025`,
                    round4_briefing:      `With lessons learned from the 2024 experience, Dr. Mendoza must structure his 2025 tax year optimally. Options include: remaining as a natural person, incorporating as an S.A.S., implementing a formal withholding program, and improving documentation practices.<br><br><strong>Opportunities:</strong> S.A.S. incorporation for asset protection and tax optimization, formal withholding at source (8% on fees), comprehensive expense documentation.<br><br>Decide: Annual compliance budget, legal structure, and whether to implement a formal withholding program.`,
                    r1_amount_label:      `Total Reported Income (COP M)`,
                    r1_amount_hint:       `Original records: 150M. Are there unreported amounts?`,
                    r1_strategy_label:    `Computer Depreciation Method`,
                    r1_strategy_hint:     `Accounting: 5yr. Tax-accelerated: 3yr`,
                    r1_strat_5yr:         `5 years (accounting method)`,
                    r1_strat_3yr:         `3 years (tax-accelerated)`,
                    r1_compliance_label:  `Include Sporadic Income`,
                    r1_compliance_hint:   `Conference (2M) + published article (2M)`,
                    r1_comp_no:           `Do not include`,
                    r1_comp_yes:          `Yes, include (COP 4M)`,
                    r2_amount_label:      `Total Deductions Claimed (COP M)`,
                    r2_amount_hint:       `Original: 26.9M. Some expenses may not be deductible.`,
                    r2_strategy_label:    `Miami Trip Treatment`,
                    r2_strategy_hint:     `Mixed business/leisure trip: COP 2.8M`,
                    r2_strat_100:         `100% deductible`,
                    r2_strat_50:          `50% deductible (business portion)`,
                    r2_strat_0:           `0% deductible (conservative)`,
                    r2_compliance_label:  `Document Related-Party Fees`,
                    r2_compliance_hint:   `COP 4.2M consulting fees to brother`,
                    r2_comp_no:           `No documentation`,
                    r2_comp_yes:          `Yes, obtain market quotes`,
                    r3_amount_label:      `Defense Budget (COP M)`,
                    r3_amount_hint:       `For legal advice, document preparation, expert opinions`,
                    r3_strategy_label:    `Response Strategy`,
                    r3_strategy_hint:     `Voluntary amendment vs. wait vs. negotiate`,
                    r3_strat_voluntary:   `Voluntary amendment (5% penalty)`,
                    r3_strat_wait:        `Wait for audit outcome (50% penalty if caught)`,
                    r3_strat_negotiate:   `Negotiate settlement`,
                    r3_compliance_label:  `Separate Rental Income`,
                    r3_compliance_hint:   `Capital income (sublease) vs. professional income`,
