        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('roundTitleDisplay');
            if (titleEl) titleEl.textContent = '— ' + t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var amountInput = document.getElementById('amountInput');
            if (amountInput) {
                amountInput.min = round.amountMin;
                amountInput.max = round.amountMax;
                amountInput.step = round.amountStep;
                amountInput.value = round.amountDefault;
            }

            var amountLabel = document.getElementById('amountLabel');
            if (amountLabel) amountLabel.textContent = t(round.amountLabelKey);

            var amountHint = document.getElementById('amountHint');
            if (amountHint) amountHint.textContent = t(round.amountHintKey);

            var strategySelect = document.getElementById('strategySelect');
            if (strategySelect) {
                strategySelect.innerHTML = '';
                for (var i = 0; i < round.strategyOptions.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.strategyOptions[i].value;
                    opt.textContent = t(round.strategyOptions[i].i18nKey);
                    strategySelect.appendChild(opt);
                }
            }

            var strategyLabel = document.getElementById('strategyLabel');
            if (strategyLabel) strategyLabel.textContent = t(round.strategyLabelKey);

            var strategyHint = document.getElementById('strategyHint');
            if (strategyHint) strategyHint.textContent = t(round.strategyHintKey);

            var complianceOptSelect = document.getElementById('complianceOptSelect');
            if (complianceOptSelect) {
                complianceOptSelect.innerHTML = '';
                for (var j = 0; j < round.complianceOptions.length; j++) {
                    var copt = document.createElement('option');
                    copt.value = round.complianceOptions[j].value;
                    copt.textContent = t(round.complianceOptions[j].i18nKey);
                    complianceOptSelect.appendChild(copt);
                }
            }

            var complianceOptLabel = document.getElementById('complianceOptLabel');
            if (complianceOptLabel) complianceOptLabel.textContent = t(round.complianceLabelKey);

            var complianceHint = document.getElementById('complianceHint');
            if (complianceHint) complianceHint.textContent = t(round.complianceHintKey);
        }
